const searchKnowledgeByLike = `-- name: SearchKnowledgeByLike :many
SELECT i.id, i.document_id, i.item_id, i.title, i.resume, i.content,
       i.source_block_ids, d.file_name, d.folder_id, f.name AS folder_name,
       i.content AS snippet
  FROM knowledge_items i
  JOIN knowledge_documents d ON d.document_id = i.document_id
  JOIN knowledge_folders f ON f.folder_id = d.folder_id
 WHERE i.tenant_id = $1
   AND i.review_status <> 'rejected'
   AND ($2::uuid IS NULL OR d.project_id = $2)
   AND (i.title ILIKE '%' || $3 || '%'
        OR i.resume ILIKE '%' || $3 || '%'
        OR i.content ILIKE '%' || $3 || '%'
        OR d.file_name ILIKE '%' || $3 || '%')
 ORDER BY i.sort_order
 LIMIT $5 OFFSET $4
`

type SearchKnowledgeByLikeParams struct {
	TenantID  uuid.UUID   `json:"tenant_id"`
	ProjectID *uuid.UUID  `json:"project_id"`
	Keyword   pgtype.Text `json:"keyword"`
	Off       int32       `json:"off"`
	Lim       int32       `json:"lim"`
}

type SearchKnowledgeByLikeRow struct {
	ID             uuid.UUID `json:"id"`
	DocumentID     uuid.UUID `json:"document_id"`
	ItemID         string    `json:"item_id"`
	Title          string    `json:"title"`
	Resume         string    `json:"resume"`
	Content        string    `json:"content"`
	SourceBlockIds []byte    `json:"source_block_ids"`
	FileName       string    `json:"file_name"`
	FolderID       uuid.UUID `json:"folder_id"`
	FolderName     string    `json:"folder_name"`
	Snippet        string    `json:"snippet"`
}

// 兜底搜索：PG simple 分词对中文支持有限，关键词匹配不到时用 LIKE。
func (q *Queries) SearchKnowledgeByLike(ctx context.Context, arg SearchKnowledgeByLikeParams) ([]SearchKnowledgeByLikeRow, error) {
	rows, err := q.db.Query(ctx, searchKnowledgeByLike,
		arg.TenantID,
		arg.ProjectID,
		arg.Keyword,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchKnowledgeByLikeRow{}
	for rows.Next() {
		var i SearchKnowledgeByLikeRow
		if err := rows.Scan(
			&i.ID,
			&i.DocumentID,
			&i.ItemID,
			&i.Title,
			&i.Resume,
			&i.Content,
			&i.SourceBlockIds,
			&i.FileName,
			&i.FolderID,
			&i.FolderName,
			&i.Snippet,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const searchKnowledgeItems = `-- name: SearchKnowledgeItems :many

SELECT i.id, i.document_id, i.item_id, i.title, i.resume, i.content,
       i.source_block_ids, d.file_name, d.folder_id, f.name AS folder_name,
       ts_rank(i.search_vector, websearch_to_tsquery('simple', $1)) AS rank,
       ts_headline('simple', i.content, websearch_to_tsquery('simple', $1),
                   'MaxWords=30, MinWords=15') AS snippet
  FROM knowledge_items i
  JOIN knowledge_documents d ON d.document_id = i.document_id
  JOIN knowledge_folders f ON f.folder_id = d.folder_id
 WHERE i.tenant_id = $2
   AND i.review_status <> 'rejected'
   AND ($3::uuid IS NULL OR d.project_id = $3)
   AND i.search_vector @@ websearch_to_tsquery('simple', $1)
 ORDER BY rank DESC, i.sort_order
 LIMIT $5 OFFSET $4
`

type SearchKnowledgeItemsParams struct {
	Keyword   string     `json:"keyword"`
	TenantID  uuid.UUID  `json:"tenant_id"`
	ProjectID *uuid.UUID `json:"project_id"`
	Off       int32      `json:"off"`
	Lim       int32      `json:"lim"`
}

type SearchKnowledgeItemsRow struct {
	ID             uuid.UUID `json:"id"`
	DocumentID     uuid.UUID `json:"document_id"`
	ItemID         string    `json:"item_id"`
	Title          string    `json:"title"`
	Resume         string    `json:"resume"`
	Content        string    `json:"content"`
	SourceBlockIds []byte    `json:"source_block_ids"`
	FileName       string    `json:"file_name"`
	FolderID       uuid.UUID `json:"folder_id"`
	FolderName     string    `json:"folder_name"`
	Rank           float32   `json:"rank"`
	Snippet        []byte    `json:"snippet"`
}

// ============ 搜索 ============
// 全文检索。
//
// 用 websearch_to_tsquery 支持 "关键词1 关键词2" 这种自然输入，
// 而不是要求用户学 to_tsquery 的 & | 语法。
func (q *Queries) SearchKnowledgeItems(ctx context.Context, arg SearchKnowledgeItemsParams) ([]SearchKnowledgeItemsRow, error) {
	rows, err := q.db.Query(ctx, searchKnowledgeItems,
		arg.Keyword,
		arg.TenantID,
		arg.ProjectID,
		arg.Off,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchKnowledgeItemsRow{}
	for rows.Next() {
		var i SearchKnowledgeItemsRow
		if err := rows.Scan(
			&i.ID,
			&i.DocumentID,
			&i.ItemID,
			&i.Title,
			&i.Resume,
			&i.Content,
			&i.SourceBlockIds,
			&i.FileName,
			&i.FolderID,
			&i.FolderName,
			&i.Rank,
			&i.Snippet,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

